CREATE TABLE app_user (id UUID PRIMARY KEY, firebase_subject VARCHAR(128) NOT NULL UNIQUE, email VARCHAR(320), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE document (id UUID PRIMARY KEY, owner_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, name VARCHAR(255) NOT NULL, content_type VARCHAR(100) NOT NULL, size_bytes BIGINT NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 26214400), object_key VARCHAR(512) NOT NULL UNIQUE, document_type VARCHAR(40) NOT NULL, processing_status VARCHAR(40) NOT NULL, favorite BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_document_owner_created ON document(owner_id, created_at DESC);
CREATE INDEX idx_document_owner_status ON document(owner_id, processing_status);
CREATE TABLE processing_job (id UUID PRIMARY KEY, document_id UUID NOT NULL REFERENCES document(id) ON DELETE CASCADE, status VARCHAR(40) NOT NULL, attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0), failure_code VARCHAR(100), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_job_status_created ON processing_job(status, created_at);
CREATE TABLE ocr_result (id UUID PRIMARY KEY, document_id UUID NOT NULL UNIQUE REFERENCES document(id) ON DELETE CASCADE, full_text TEXT NOT NULL, language VARCHAR(16) NOT NULL, confidence NUMERIC(5,4) NOT NULL CHECK (confidence BETWEEN 0 AND 1), pages INTEGER NOT NULL CHECK (pages > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE document_analysis (id UUID PRIMARY KEY, document_id UUID NOT NULL REFERENCES document(id) ON DELETE CASCADE, analysis_type VARCHAR(40) NOT NULL, result_json JSONB NOT NULL, provider VARCHAR(40) NOT NULL, model VARCHAR(80) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(document_id, analysis_type));
